{
  "action": "T1_GENERAL",
  "conditions": [
    {"attr": "customer_tier", "op": "eq", "value": "enterprise"},
    {"attr": "severity", "op": "lte", "value": 4},
    {"attr": "product", "op": "eq", "value": "dashboard"}
  ],
  "beats": [],
  "loses_to": [],
  "note": "Primera regla del sistema. Cliente enterprise con severidad baja en dashboard va a T1_GENERAL, ya que no hay indicios de urgencia técnica ni de seguridad. Se abstrae a cualquier severidad <=4 para cubrir todos los casos no críticos de dashboard enterprise."
}

{
  "action": "T2_TECHNICAL",
  "conditions": [
    {"attr": "product", "op": "eq", "value": "dashboard"},
